@@ -212,6 +226,25 @@ int vpt1_gw_commit(struct vpt1_gw *gw, u64 revision, u64 now_ns, bool *disruptiv
 int vpt1_gw_status(struct vpt1_gw *gw, u64 now_ns, struct vpt1_status *out);
 void vpt1_gw_counters(const struct vpt1_gw *gw, u64 out[VPT1_E_COUNT]);

+/*
+ * Liveness. A relationship with a current generation sends a PING (a fresh random challenge) every
+ * VPT1_PING_NS from the gateway worker and answers every authenticated PING under its current
+ * generation with a PONG. Only a PONG that echoes one of at most VPT1_CHALLENGES live challenges
+ * counts, once, as a round trip (inbound data or PINGs alone do not). With none for VPT1_LIVE_NS the
+ * peer is closed: application admission fails, its continuity dies, and only a new session (a fresh
+ * generation install, which replaces even a still-valid current one) opens it again. A lapsed lease
+ * silences both sending and answering, so a gateway without a controller goes quiet.
+ *
+ * challenge: a challenge if one is due and a slot is free, else false. pong: true when it matched.
+ * closed: whether the peer has had no round trip for VPT1_LIVE_NS. is_current: whether @gen is the
+ * peer's current generation (liveness is not accepted under a next or retiring one).
+ */
+bool vpt1_peer_live_challenge(struct vpt1_peer *peer, u64 now_ns, u8 out[VPT1_CHALLENGE_LEN]);
+bool vpt1_peer_live_pong(struct vpt1_peer *peer, const u8 c[VPT1_CHALLENGE_LEN], u64 now_ns);
+bool vpt1_peer_live_closed(struct vpt1_peer *peer, u64 now_ns);
+bool vpt1_peer_gen_is_current(struct vpt1_peer *peer, const struct vpt1_generation *gen);
+bool vpt1_gw_lease_live(struct vpt1_gw *gw, u64 now_ns);
+
 /*
  * Kernel-issued establishment attempts (TECHNICAL_DESIGN section 5). A peer has at most one pending
  * attempt: an attempt ID and a receive locator the kernel chose (random, nonzero, collision-checked
@@ -355,6 +388,9 @@ void vpt1_admit_done(struct vpt1_peer *peer);
 struct vpt1_gw_ops {
 	int (*bind)(struct vpt1_gw *gw, __be32 local, u32 ifindex);
 	void (*unbind)(struct vpt1_gw *gw);
+	/* Seal and send one encrypted control record under the peer's current generation. Any context. */
+	int (*send_control)(struct vpt1_gw *gw, struct vpt1_peer *peer, u8 subtype, const u8 *payload,
+			    unsigned int len);
 };
 void vpt1_gw_set_ops(const struct vpt1_gw_ops *ops);
 struct net;
diff --git a/kernel/runtime/datapath.c b/kernel/runtime/datapath.c
--- a/kernel/runtime/datapath.c
+++ b/kernel/runtime/datapath.c
@@ -192,6 +192,89 @@ bool vpt1_dp_xmit(struct vpt1_gw *gw, struct net_device *dev, struct sk_buff *sk
 	return sent;
 }

+/*
+ * Seal and send one encrypted control record (PING, PONG) under the peer's current generation. It
+ * takes a counter of that generation like data does, so it counts toward the key's limits, but it
+ * is not an inner packet: there is no policy or flow check, and it never reaches vpn0. A lapsed
+ * lease, a stopping gateway or a closed peer sends nothing. Any context.
+ */
+static int vpt1_dp_send_control(struct vpt1_gw *gw, struct vpt1_peer *peer, u8 subtype,
+				const u8 *payload, unsigned int len)
+{
+	struct vpt1_generation *gen;
+	struct vpt1_route route;
+	struct flowi4 fl4 = {};
+	struct sk_buff *out;
+	struct rtable *rt;
+	struct vpt1_dp *dp;
+	u64 counter, now, remote_rx;
+	unsigned int total;
+	int err = -ENOTCONN;
+	u8 *buf;
+
+	now = ktime_get_boottime_ns();
+	local_bh_disable();
+	rcu_read_lock();
+	dp = vpt1_gw_priv(gw);
+	if (!dp || !vpt1_gw_lease_live(gw, now) ||
+	    vpt1_gw_peer_route(gw, vpt1_peer_slot(peer), &route))
+		goto unlock;
+	gen = vpt1_peer_tx_generation_get(peer, now, &remote_rx);
+	if (!gen) {
+		err = -ENOKEY;
+		goto unlock;
+	}
+	err = vpt1_generation_tx_reserve(gen, VPT1_PREFIX_LEN + len, now, &counter);
+	if (err)
+		goto put;
+	total = VPT1_AAD_LEN + VPT1_PREFIX_LEN + len + VPT1_TAG_LEN;
+	out = alloc_skb(total + LL_MAX_HEADER + sizeof(struct iphdr) + sizeof(struct udphdr) + 16,
+			GFP_ATOMIC);
+	if (!out) {
+		err = -ENOMEM;
+		goto put;
+	}
+	skb_reserve(out, LL_MAX_HEADER + sizeof(struct iphdr) + sizeof(struct udphdr) + 16);
+	buf = skb_put(out, total);
+	memcpy(buf, "VPT1", 4);
+	buf[4] = VPT1_RECORD;
+	buf[5] = 0;
+	put_unaligned_be16(total - VPT1_ENVELOPE_LEN, buf + 6);
+	put_unaligned_be64(remote_rx, buf + 8);
+	put_unaligned_be64(counter, buf + VPT1_ENVELOPE_LEN);
+	buf[VPT1_AAD_LEN] = subtype;
+	buf[VPT1_AAD_LEN + 1] = 0;
+	put_unaligned_be16(len, buf + VPT1_AAD_LEN + 2);
+	memcpy(buf + VPT1_AAD_LEN + VPT1_PREFIX_LEN, payload, len);
+	err = aead_run(vpt1_generation_tx_aead(gen), buf, total, VPT1_PREFIX_LEN + len, counter, true);
+	if (err)
+		goto free;
+	fl4.daddr = route.endpoint;
+	fl4.saddr = route.local;
+	fl4.flowi4_oif = route.ifindex;
+	fl4.flowi4_proto = IPPROTO_UDP;
+	rt = ip_route_output_key(vpt1_gw_net(gw), &fl4);
+	if (IS_ERR(rt)) {
+		err = PTR_ERR(rt);
+		goto free;
+	}
+	udp_tunnel_xmit_skb(rt, dp->sock->sk, out, fl4.saddr, fl4.daddr, 0,
+			    ip4_dst_hoplimit(&rt->dst), htons(IP_DF), htons(VPT1_UDP_PORT),
+			    route.port, false, false, 0);
+	out = NULL;
+	vpt1_gw_stat_inc(gw, subtype == VPT1_PING ? VPT1_E_TX_PING : VPT1_E_TX_PONG);
+	err = 0;
+free:
+	if (out)
+		kfree_skb(out);
+put:
+	vpt1_generation_put(gen);
+unlock:
+	rcu_read_unlock();
+	local_bh_enable();
+	return err;
+}
+
 /* Process context, cfg_lock held: send one handshake message from the bound socket. */
 int vpt1_dp_send_exchange(struct vpt1_gw *gw, unsigned int slot, const void *buf, size_t len)
 {
@@ -364,7 +447,34 @@ static int vpt1_dp_rcv(struct sock *sk, struct sk_buff *skb)
 	/* A record authenticated under a next generation makes it the one we send with. */
 	vpt1_peer_rx_confirmed(peer, gen, now);

-	/* Authenticated. Only IPv4 data records are handled by this data path. */
+	/* Authenticated: an encrypted control record, or an IPv4 data record for the policy path. */
+	if (!vpt1_parse_authenticated_plaintext(skb->data + VPT1_AAD_LEN, ptlen, VPT1_INNER_CAP_MAX,
+						&plain) &&
+	    plain.subtype != VPT1_IPV4) {
+		/*
+		 * Liveness only: PING is answered, PONG is matched. Only under the current generation (a
+		 * next or retiring one does not speak for the session), and only while the lease is live.
+		 * Every other subtype is authenticated but not acted on here.
+		 */
+		if ((plain.subtype == VPT1_PING || plain.subtype == VPT1_PONG) &&
+		    vpt1_gw_lease_live(gw, now) && vpt1_peer_gen_is_current(peer, gen)) {
+			if (plain.subtype == VPT1_PING) {
+				vpt1_gw_stat_inc(gw, VPT1_E_RX_PING);
+				vpt1_dp_send_control(gw, peer, VPT1_PONG, plain.payload,
+						     plain.payload_len);
+			} else if (vpt1_peer_live_pong(peer, plain.payload, now)) {
+				vpt1_gw_stat_inc(gw, VPT1_E_RX_PONG);
+			} else {
+				vpt1_gw_stat_inc(gw, VPT1_E_RX_CONTROL_DROPPED);
+			}
+		} else {
+			vpt1_gw_stat_inc(gw, VPT1_E_RX_CONTROL_DROPPED);
+		}
+		vpt1_generation_put(gen);
+		vpt1_peer_put(peer);
+		kfree_skb(skb);
+		return 0;
+	}
 	if (vpt1_parse_authenticated_plaintext(skb->data + VPT1_AAD_LEN, ptlen,
 					       VPT1_INNER_CAP_MAX, &plain) ||
 	    plain.subtype != VPT1_IPV4 ||
@@ -505,6 +615,7 @@ static void vpt1_dp_unbind(struct vpt1_gw *gw)
 }

 const struct vpt1_gw_ops vpt1_dp_ops = {
+	.send_control = vpt1_dp_send_control,
 	.bind = vpt1_dp_bind,
 	.unbind = vpt1_dp_unbind,
 };
diff --git a/kernel/runtime/gateway.c b/kernel/runtime/gateway.c
--- a/kernel/runtime/gateway.c
+++ b/kernel/runtime/gateway.c
@@ -23,6 +23,7 @@
 #include "vpt1_gateway.h"
 #include "vpt1_generation.h"
 #include "vpt1_ip.h"
+#include "vpt1_wire.h"

 #ifdef VPT1_DEBUG
 atomic_t vpt1_dbg_stall_expiry = ATOMIC_INIT(0);
@@ -115,6 +116,15 @@ struct vpt1_peer {
 	bool init_valid;
 	u8 init_id[VPT1_ATTEMPT_ID_LEN];
 	u64 init_deadline_ns;
+	/* Liveness, peer lock. */
+	bool live_armed;
+	bool live_lost; /* The closure has been acted on. */
+	u64 live_last_ns;
+	u64 ping_due_ns;
+	struct {
+		u8 c[VPT1_CHALLENGE_LEN];
+		u64 expiry_ns;
+	} chal[VPT1_CHALLENGES];
 	atomic_t inflight;
 	struct vpt1_bucket new_flows;
 	struct vpt1_bucket errors;
@@ -146,6 +156,7 @@ struct vpt1_gw {
 	atomic64_t ctr[VPT1_E_COUNT];
 	struct delayed_work expiry_work;
 	struct delayed_work gens_work; /* Wipes retired generations after their grace. */
+	struct delayed_work live_work; /* PINGs, and acts on a closed peer. */
 	/* Bounded job queue (vpt1_job_queue); job_lock is a leaf. */
 	spinlock_t job_lock;
 	struct list_head jobs;
@@ -453,6 +464,9 @@ static void peer_take_gens_locked(struct vpt1_peer *peer, struct vpt1_gens *out)
 	if (out->cont)
 		atomic_set(&out->cont->dead, 1);
 	peer->cont = NULL;
+	peer->live_armed = false;
+	peer->live_lost = false;
+	memset(peer->chal, 0, sizeof(peer->chal));
 	peer->gen = NULL;
 	peer->next_gen = NULL;
 	peer->prev_gen = NULL;
@@ -810,6 +824,141 @@ void vpt1_peer_rx_confirmed(struct vpt1_peer *peer, struct vpt1_generation *gen,
 		peer_promoted(peer, retired);
 }

+/* Liveness -------------------------------------------------------------------- */
+
+/* Peer lock held. */
+static bool live_closed_locked(const struct vpt1_peer *peer, u64 now_ns)
+{
+	return peer->live_armed && now_ns > peer->live_last_ns &&
+	       now_ns - peer->live_last_ns >= VPT1_LIVE_NS;
+}
+
+/* Peer lock held: a new session starts the clock; the first PING follows shortly. */
+static void live_arm_locked(struct vpt1_peer *peer, u64 now_ns)
+{
+	peer->live_armed = true;
+	peer->live_lost = false;
+	peer->live_last_ns = now_ns;
+	peer->ping_due_ns = now_ns + VPT1_PING_FIRST_NS;
+	memset(peer->chal, 0, sizeof(peer->chal));
+}
+
+bool vpt1_peer_live_closed(struct vpt1_peer *peer, u64 now_ns)
+{
+	bool closed;
+
+	spin_lock_bh(&peer->lock);
+	closed = live_closed_locked(peer, now_ns);
+	spin_unlock_bh(&peer->lock);
+	return closed;
+}
+
+bool vpt1_peer_live_challenge(struct vpt1_peer *peer, u64 now_ns, u8 out[VPT1_CHALLENGE_LEN])
+{
+	unsigned int i;
+	bool made = false;
+
+	spin_lock_bh(&peer->lock);
+	if (peer->live_armed && peer->state == VPT1_PEER_READY && peer->gen &&
+	    !live_closed_locked(peer, now_ns) && now_ns >= peer->ping_due_ns) {
+		for (i = 0; i < VPT1_CHALLENGES; i++) {
+			if (peer->chal[i].expiry_ns > now_ns)
+				continue; /* Still answerable. */
+			get_random_bytes(peer->chal[i].c, VPT1_CHALLENGE_LEN);
+			peer->chal[i].expiry_ns = now_ns + VPT1_CHALLENGE_NS;
+			memcpy(out, peer->chal[i].c, VPT1_CHALLENGE_LEN);
+			peer->ping_due_ns = now_ns + VPT1_PING_NS;
+			made = true;
+			break;
+		}
+	}
+	spin_unlock_bh(&peer->lock);
+	return made;
+}
+
+bool vpt1_peer_live_pong(struct vpt1_peer *peer, const u8 c[VPT1_CHALLENGE_LEN], u64 now_ns)
+{
+	unsigned int i;
+	bool matched = false;
+
+	spin_lock_bh(&peer->lock);
+	/* A closed peer needs a new session; a late answer does not reopen it. */
+	if (peer->live_armed && !live_closed_locked(peer, now_ns)) {
+		for (i = 0; i < VPT1_CHALLENGES; i++) {
+			if (peer->chal[i].expiry_ns > now_ns &&
+			    !memcmp(peer->chal[i].c, c, VPT1_CHALLENGE_LEN)) {
+				peer->chal[i].expiry_ns = 0; /* Consumed: it cannot refresh health again. */
+				memzero_explicit(peer->chal[i].c, VPT1_CHALLENGE_LEN);
+				if (now_ns > peer->live_last_ns)
+					peer->live_last_ns = now_ns;
+				matched = true;
+				break;
+			}
+		}
+	}
+	spin_unlock_bh(&peer->lock);
+	return matched;
+}
+
+bool vpt1_peer_gen_is_current(struct vpt1_peer *peer, const struct vpt1_generation *gen)
+{
+	bool current_gen;
+
+	spin_lock_bh(&peer->lock);
+	current_gen = gen && gen == peer->gen;
+	spin_unlock_bh(&peer->lock);
+	return current_gen;
+}
+
+bool vpt1_gw_lease_live(struct vpt1_gw *gw, u64 now_ns)
+{
+	return !READ_ONCE(gw->stopping) && READ_ONCE(gw->live_epoch) &&
+	       now_ns < READ_ONCE(gw->deadline_ns);
+}
+
+/* Once a second: PING each live relationship when due, and act on a peer that has gone silent. */
+static void live_work_fn(struct work_struct *work)
+{
+	struct vpt1_gw *gw = container_of(to_delayed_work(work), struct vpt1_gw, live_work);
+	u64 now = ktime_get_boottime_ns();
+	bool again = false;
+	unsigned int slot;
+
+	if (!vpt1_gw_get(gw))
+		return;
+	mutex_lock(&gw->cfg_lock);
+	for (slot = 1; slot <= VPT1_MAX_PEERS && !gw->stopping; slot++) {
+		struct vpt1_peer *peer = peer_locked(gw, slot);
+		u8 challenge[VPT1_CHALLENGE_LEN];
+		bool first_loss = false, armed;
+
+		if (!peer)
+			continue;
+		spin_lock_bh(&peer->lock);
+		armed = peer->live_armed && peer->state == VPT1_PEER_READY;
+		if (armed && live_closed_locked(peer, now) && !peer->live_lost) {
+			/* Flow continuity ends with the session: nothing may complete under it. */
+			peer->live_lost = true;
+			first_loss = true;
+			if (peer->cont)
+				atomic_set(&peer->cont->dead, 1);
+		}
+		spin_unlock_bh(&peer->lock);
+		if (first_loss)
+			ctr_inc(gw, VPT1_E_LIVENESS_LOST);
+		if (!armed)
+			continue;
+		again = true;
+		if (vpt1_gw_lease_live(gw, now) && vpt1_gw_ops_ptr && vpt1_gw_ops_ptr->send_control &&
+		    vpt1_peer_live_challenge(peer, now, challenge))
+			vpt1_gw_ops_ptr->send_control(gw, peer, VPT1_PING, challenge, VPT1_CHALLENGE_LEN);
+	}
+	mutex_unlock(&gw->cfg_lock);
+	if (again && vpt1_gw_wq && !READ_ONCE(gw->stopping))
+		queue_delayed_work(vpt1_gw_wq, &gw->live_work, HZ);
+	vpt1_gw_put(gw);
+}
+
 /* Releases retired generations whose grace has run out. */
